import{c as e,Q as r,j as d,m as o}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"LLM Memory 控制與實作深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-05-31-llm-memory-deep-research.md","filePath":"research/reports/archive/2026-05-31-llm-memory-deep-research.md","lastUpdated":1780842316000}'),n={name:"research/reports/archive/2026-05-31-llm-memory-deep-research.md"};function a(s,t,i,l,g,m){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="llm-memory-控制與實作深度研究報告" tabindex="-1">LLM Memory 控制與實作深度研究報告 <a class="header-anchor" href="#llm-memory-控制與實作深度研究報告" aria-label="Permalink to &quot;LLM Memory 控制與實作深度研究報告&quot;">​</a></h1><blockquote><p><strong>方法論</strong>：research-hub:deep — 每 claim 標 [P/O/C/E]；D2 交叉驗證 ≥2 來源；失效 claim 標 ⚠️ 不刪。 <strong>語料</strong>：本地 28 篇一級文獻，2023–2026；web search 未使用（語料覆蓋充足）。 <strong>撰寫日期</strong>：2026-05-31 <strong>2026-06-05 增量複查</strong>：對照 papers/INDEX 當前 Memory 語料，本報告所列 28 篇分配論文皆已實質引用（grep 親驗：scm/delta-mem/rethinking-mem-ops/reasoningbank/hindsight/chronos/externalization/mnemonic-sovereignty 各 1–5×）；<strong>無新 in-domain Memory 論文未覆蓋</strong>，本次無內容變更。同期 4 篇 in-domain 新論文全歸 Harness 側（見 harness-engineering-deep-research §A/§C2/§D）。</p></blockquote><hr><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>LLM 記憶系統已從單純的 context window 擴充，演化為多層次、多策略的控制工程領域。本報告從三個維度（控制機制、實作架構、失效與安全）深度綜合 28 篇一級來源，產出生產級 memory 的「控制旋鈕表」，並指出整合式記憶（consolidation）本身可能是最大風險所在。</p><hr><h2 id="a-控制機制" tabindex="-1">A. 控制機制 <a class="header-anchor" href="#a-控制機制" aria-label="Permalink to &quot;A. 控制機制&quot;">​</a></h2><h3 id="a1-stm-ltm-分層架構" tabindex="-1">A1. STM/LTM 分層架構 <a class="header-anchor" href="#a1-stm-ltm-分層架構" aria-label="Permalink to &quot;A1. STM/LTM 分層架構&quot;">​</a></h3><p><strong>MemGPT 的 OS 類比</strong> [P：2310-08560] 是分層架構的里程碑：將 LLM 類比作業系統，定義 <strong>主記憶（Main Context）</strong> 為處理器可直接操作的 RAM，<strong>外部記憶（External Storage）</strong> 為磁碟，並實作顯式的分頁換入換出（page in/out）中斷機制。函式呼叫觸發 <code>memory_load</code>、<code>memory_save</code> 操作，讓 LLM 自行決定何時換頁——這是記憶主控性（agentic memory control）的起點。</p><p><strong>MemoryOS</strong> [P：2506-06326] 進一步精煉為三層：短期（Short-term, STM）→ 中期（Mid-term, MTM）→ 長期（Long-term, LTM）。升格規則：STM→MTM 依對話鏈 FIFO 原則，MTM→LTM 採分段頁面組織（segmented page）加熱度門檻（heat threshold）。在 LoCoMo benchmark 上對 GPT-4o-mini 達到 F1 +49.11%，BLEU-1 +46.18% [P：2506-06326]。</p><p><strong>AgeMem（Agentic Memory Unified LTM+STM）</strong> [P：2601-01885] 批評既有系統「獨立優化 LTM 與 STM 後以臨時方式組合」，改採工具導向行動（tool-as-action）讓 agent 自主執行 store/retrieve/update/summarize/discard，以三階段漸進 RL（GRPO）端對端學習記憶管理策略——超越 5 個長視地平線 benchmark 的所有基線 [P：2601-01885]。</p><p><strong>SCM（Self-Controlled Memory）</strong> [P：2304-13343] 的貢獻在於提出 <strong>記憶串流（memory stream）+ 記憶控制器（memory controller）</strong> 的 plug-and-play 架構，透過 LLM-based 控制器決定何時觸發檢索，無需模型修改，相容任意指令模型 [P：2304-13343]。</p><p><strong>交叉驗證</strong>：MemGPT [P：2310-08560]、MemoryOS [P：2506-06326]、memory-autonomous-llm-agents-survey [O：2603-07670] 均獨立確認三層分層的必要性；survey-memory-mechanism [O：2404-13501] 進一步指出缺乏分層的系統在長對話中性能退化明顯 [P+O D2]。</p><hr><h3 id="a2-寫入、讀取、遺忘策略" tabindex="-1">A2. 寫入、讀取、遺忘策略 <a class="header-anchor" href="#a2-寫入、讀取、遺忘策略" aria-label="Permalink to &quot;A2. 寫入、讀取、遺忘策略&quot;">​</a></h3><p><strong>六大核心操作（Rethinking Memory）</strong> [P：2505-00675] 提供目前最完整的操作分類：</p><ol><li><strong>Consolidation（整合）</strong>：多條記憶壓縮為緊湊表示</li><li><strong>Updating（更新）</strong>：修改現有記憶以反映新資訊</li><li><strong>Indexing（索引）</strong>：建立檢索結構（密集向量或稀疏 BM25）</li><li><strong>Forgetting（遺忘）</strong>：主動淘汰過時或低相關記憶</li><li><strong>Retrieval（檢索）</strong>：查詢相關記憶注入 context</li><li><strong>Condensation（壓縮）</strong>：縮短記憶表示（有別於 Consolidation）</li></ol><p><strong>Mem0 的生產實作</strong> [P：2504-19413] 將上述操作包裝成 API：每次對話後 LLM 自動提取 salient 資訊，透過「ADD / UPDATE / DELETE / NONE」四動作完成增量寫入，搭配圖結構變體捕捉實體關係。在 LOCOMO benchmark 較 OpenAI memory-augmented approach 達 +26% relative improvement [P：2504-19413]，且相較全上下文方法降低 p95 latency 91%、token 成本 90% [P：2504-19413]。</p><p><strong>MemoryBank 的艾賓浩斯遺忘曲線</strong> [P：2305-10250]：實作基於遺忘曲線（Ebbinghaus forgetting curve）的記憶強化機制，依時間衰減決定記憶「強度」，超過閾值才列為活躍記憶，模擬人類的「複習效應」[P：2305-10250]。</p><p><strong>δ-mem 的線性狀態更新</strong> [P：2605-12357]：不同於外部 DB 的顯式 CRUD，δ-mem 用 <strong>delta-rule 學習</strong>（Widrow-Hoff 法則）維護一個固定大小 8×8 的線上聯想記憶矩陣（associative memory state matrix），在凍結的全注意力模型上生成低秩修正（low-rank correction）。實測平均提升 frozen backbone 的 1.10×，memory-heavy benchmark 達 1.31×（MemoryAgentBench）[P：2605-12357]，完全不需要 fine-tuning 或 backbone 替換。</p><hr><h3 id="a3-時序控制" tabindex="-1">A3. 時序控制 <a class="header-anchor" href="#a3-時序控制" aria-label="Permalink to &quot;A3. 時序控制&quot;">​</a></h3><p><strong>Chronos</strong> [P：2603-16862] 是迄今最完整的時序感知記憶框架：將原始對話分解為 <strong>主詞-動詞-賓語（SVO）事件元組</strong>，附加 ISO 8601 datetime 範圍與實體別名，建立「事件日曆（event calendar）」與「輪次日曆（turn calendar）」雙索引。查詢時動態生成每個問題的客製化檢索指引（dynamic prompting），含時間範圍過濾與多跳推理的迭代工具呼叫迴圈。在 LongMemEvalS (500 questions) 上 Chronos High 達 <strong>95.60%</strong>，超越次優系統 7.67%，事件日曆單獨貢獻 58.9% 增益 [P：2603-16862]。</p><p><strong>交叉驗證</strong>：Hindsight [P：2512-12818] 的四網絡架構（world facts / agent experiences / entity summaries / evolving beliefs）亦強調時間與實體感知，在 LongMemEval 達 83.6%（20B 開源超越 GPT-4o）[P：2512-12818]，與 Chronos 的時序設計形成 D2 驗證。</p><hr><h3 id="a4-operations-抽象" tabindex="-1">A4. Operations 抽象 <a class="header-anchor" href="#a4-operations-抽象" aria-label="Permalink to &quot;A4. Operations 抽象&quot;">​</a></h3><p><strong>Rethinking Memory</strong> [P：2505-00675] 的最大貢獻是區分 <strong>參數記憶（Parametric Memory，存於模型權重）</strong> 與 <strong>上下文記憶（Contextual Memory，存於模型外部）</strong>，並指出前者需透過微調或知識編輯（ROME、MEMIT）更新，後者透過 CRUD 操作更新——兩種更新路徑的成本與可逆性完全不同。</p><p><strong>security-long-term-memory</strong> [P：2604-16548] 將操作抽象成六階段生命週期：Write → Store → Retrieve → Execute → Share → Forget/Rollback，對應四個安全目標（Integrity、Confidentiality、Availability、Governance），定義「記憶主權（Mnemonic Sovereignty）」為可驗證、可恢復的治理能力 [P：2604-16548]。</p><hr><h2 id="b-實作架構" tabindex="-1">B. 實作架構 <a class="header-anchor" href="#b-實作架構" aria-label="Permalink to &quot;B. 實作架構&quot;">​</a></h2><h3 id="b1-檢索式記憶-retrieval-based" tabindex="-1">B1. 檢索式記憶（Retrieval-based） <a class="header-anchor" href="#b1-檢索式記憶-retrieval-based" aria-label="Permalink to &quot;B1. 檢索式記憶（Retrieval-based）&quot;">​</a></h3><p><strong>HippoRAG</strong> [P：2405-14831]（NeurIPS 2024）採用神經科學靈感——海馬體索引理論（Hippocampal Indexing Theory）：LLM 類比新皮質（知識儲存），知識圖譜 + Personalized PageRank（PPR）類比海馬體（索引建立）。索引階段：LLM 抽取 KG 三元組；檢索階段：PPR 從 seed 節點沿圖傳播，自動找橋接概念（bridge concepts）。在多跳問答上超越現有 RAG 方法 20%，同時達到 IRCoT 效果但快 6–13×、便宜 10–30× [P：2405-14831]。</p><p><strong>MemoryBank</strong> [P：2305-10250] 以語義向量 DB 儲存對話事件與用戶特質，結合遺忘曲線排序，在 ChatGPT（3.5）上下支援跨 session 長期個人化對話 [P：2305-10250]。</p><p><strong>MemoryOS</strong> [P：2506-06326] 的三層檢索：STM（精確 embedding 匹配）→ MTM（分段語義檢索）→ LTM（個性化圖檢索）。熱度分數（heat score）融合頻率、近期度、相關性 [P：2506-06326]。</p><hr><h3 id="b2-agentic-自組織記憶" tabindex="-1">B2. Agentic 自組織記憶 <a class="header-anchor" href="#b2-agentic-自組織記憶" aria-label="Permalink to &quot;B2. Agentic 自組織記憶&quot;">​</a></h3><p><strong>A-MEM</strong> [P：2502-12110]（NeurIPS 2025）採 <strong>Zettelkasten 筆記系統</strong>哲學：每筆記憶進入時，LLM 自動生成上下文描述、關鍵詞、標籤，並主動分析歷史記憶建立連結網絡。記憶的互聯性（interconnectivity）比單純的相似度檢索捕捉更豐富的關聯 [P：2502-12110]。</p><p><strong>ReasoningBank</strong> [P：2509-25140] 不儲存原始軌跡，而是蒸餾<strong>可泛化推理策略（generalizable reasoning strategies）</strong>——從 agent 自我評判的成功與失敗經驗中提取。MaTTS（Memory-aware Test-Time Scaling）透過更多算力生成多元對比經驗，形成「更好記憶 → 更有效 scaling → 更好記憶」的正向循環。在 web browsing + software engineering benchmark 超越儲存原始軌跡或只儲存成功例子的方法 [P：2509-25140]。</p><p><strong>Hindsight 四網絡</strong> [P：2512-12818]：Retain（記憶寫入）→ Recall（查詢）→ Reflect（更新）三核心操作，組織四類記憶網絡（World facts / Agent experiences / Entity summaries / Evolving beliefs），強調「證據與推理分離」——不混合原始事實與推論，確保可解釋性 [P：2512-12818]。</p><hr><h3 id="b3-test-time-learning-與-context-engineering" tabindex="-1">B3. Test-Time Learning 與 Context Engineering <a class="header-anchor" href="#b3-test-time-learning-與-context-engineering" aria-label="Permalink to &quot;B3. Test-Time Learning 與 Context Engineering&quot;">​</a></h3><p><strong>Dynamic Cheatsheet</strong> [P：2504-07952] 是 test-time learning 的早期代表：在推理時累積可更新的「作弊表」，讓模型在不重訓練的前提下快速適應新資訊或偏好 [P：2504-07952]。</p><p><strong>ACE（Agentic Context Engineering）</strong> [P：2510-04618]（ICLR 2026）將 context 視為「演化式作戰手冊（evolving playbooks）」，採三模組流程：Generator（生成軌跡）→ Reflector（提取 insights，含失敗分析）→ Curator（增量 delta 更新，語義去重）。明確對抗兩大失效模式：<strong>brevity bias</strong>（因求簡潔丟棄細節）與 <strong>context collapse</strong>（整體改寫破壞積累知識）。在 AppWorld leaderboard 以小型開源模型匹敵頂級生產 GPT-4.1 agent [P：2510-04618]。</p><p><strong>交叉驗證</strong>：useful-memories-faulty [P：2605-12978] 與 ACE [P：2510-04618] 均獨立識別「LLM-based 整合/改寫導致資訊退化」問題，ACE 的增量 delta 更新正是對此的工程回應 [P D2]。</p><hr><h3 id="b4-context-vs-memory-取捨" tabindex="-1">B4. Context vs Memory 取捨 <a class="header-anchor" href="#b4-context-vs-memory-取捨" aria-label="Permalink to &quot;B4. Context vs Memory 取捨&quot;">​</a></h3><p><strong>Beyond Context Window</strong> [P：2603-04814] 是迄今最大規模的直接實証比較：<strong>長上下文（Long-context）以 33.4–35.2 個百分點的準確率優勢大幅領先記憶壓縮方案</strong>，但記憶方案在約 10 輪對話後（100K token context size）在成本上變得合理——記憶系統達到 35:1 壓縮比，代價是顯著的資訊損失 [P：2603-04814]。</p><blockquote><p>⚠️ <strong>注意</strong>：此結論基於 2026 年 3 月的模型，長上下文模型代價正在快速下降，記憶 vs 長上下文的 crossover 點會隨時移動。</p></blockquote><p><strong>Lost in the Middle</strong> [P：2307-03172] 揭示即使用長上下文，<strong>位置偏差（positional bias）</strong> 問題嚴重：相關資訊在上下文開頭或結尾時性能最高，中段性能顯著退化（U 形曲線）。此問題在明確為長上下文訓練的模型上仍持續，表明記憶系統的結構化檢索有其存在價值 [P：2307-03172]。</p><p><strong>Recursive Language Models（RLMs）</strong> [P：2512-24601]（MIT CSAIL）提出第三條路：LLM 把超長輸入視為外部環境，透過程式化遞迴呼叫自身處理任意長度 prompt。RLM-Qwen3-8B 超越 Qwen3-8B 基座 28%（中位數），在三項長上下文任務上接近 vanilla GPT-5 品質；對比 compaction 方法提升中位數 26% [P：2512-24601]。</p><p><strong>MemTool</strong> [P：2507-21428] 填補短期工具記憶（tool context）的空白：提出三模式（Autonomous / Workflow / Hybrid）管理 100+ 輪多輪對話中的動態工具集，Autonomous 模式下推理模型達 90–94% 工具移除效率（相當於準確的「工具遺忘」），中型模型僅 0–60% [P：2507-21428]。</p><p><strong>Externalization</strong> [P：2604-08224] 從認知架構角度統一框架：記憶（Memory）、技能（Skills）、協議（Protocols）、Harness 都是 LLM 的外部化（externalization），其演化軌跡：Monolithic context → Retrieval stores → Hierarchical systems [P：2604-08224]。</p><hr><h3 id="b5-cache-層記憶" tabindex="-1">B5. Cache 層記憶 <a class="header-anchor" href="#b5-cache-層記憶" aria-label="Permalink to &quot;B5. Cache 層記憶&quot;">​</a></h3><p><strong>Don&#39;t Break the Cache</strong> [P：2601-06007] 分析三種快取策略在 agentic coding 工具上的效果：<strong>system-prompt-only 快取為最優預設策略</strong>，達到 78.5% 成本降低、22.9% TTFT 改善（Claude Sonnet 4.5）。動態內容（工具呼叫結果、agent 軌跡）頻繁破壞快取是主要風險；Anthropic cache TTL 5 分鐘（可延長至 1 小時）、90% token 費用折扣 [P：2601-06007]。</p><p>快取本質上是 STM 的硬體層：重複前綴的 KV states 複用，可視為 immutable STM 的效率最佳化 [C：基於 2601-06007 + 2601-01885 推導]。</p><hr><h3 id="b6-多代理記憶" tabindex="-1">B6. 多代理記憶 <a class="header-anchor" href="#b6-多代理記憶" aria-label="Permalink to &quot;B6. 多代理記憶&quot;">​</a></h3><p><strong>Multi-Agent Memory from Computer Architecture</strong> [P：2603-10062]（Position Paper）將多代理記憶問題框架化為計算機架構問題：</p><ul><li><strong>共享記憶（Shared Memory）</strong> 類比 SMP；<strong>分散記憶（Distributed Memory）</strong> 類比分散式計算</li><li>三層階層：I/O 層（agent-世界交換）→ 快取層（高頻存取）→ 主記憶層（持久化）</li><li><strong>最緊迫挑戰：多代理快取一致性（Cache Coherency）</strong>——當多個 agent 並發存取或修改共享記憶時，語義豐富性 + 非確定性推理使傳統 cache coherency 協議無法直接套用 [P：2603-10062]</li></ul><hr><h2 id="c-失效與安全" tabindex="-1">C. 失效與安全 <a class="header-anchor" href="#c-失效與安全" aria-label="Permalink to &quot;C. 失效與安全&quot;">​</a></h2><h3 id="c1-記憶污染與整合退化" tabindex="-1">C1. 記憶污染與整合退化 <a class="header-anchor" href="#c1-記憶污染與整合退化" aria-label="Permalink to &quot;C1. 記憶污染與整合退化&quot;">​</a></h3><p><strong>Useful Memories Become Faulty</strong> [P：2605-12978] 是 2026 年最重要的記憶安全警告：</p><ul><li><strong>核心發現</strong>：連續整合 ground-truth 成功解答軌跡後，GPT-5.4 在 ARC-AGI 問題上失敗率 <strong>54%</strong>（從 100% 成功跌至 46%）[P：2605-12978]</li><li><strong>退化曲線非單調</strong>：utility 先升後降，最終落到 no-memory 基線以下（WebShop：0.64 → 0.20）</li><li><strong>三種失效機制</strong>： <ol><li><strong>Misgrouping</strong>：將不同問題家族的 episode 錯誤歸類，產生跨類別混合規則</li><li><strong>Interference</strong>：抽象化剝除適用條件，造成過度泛化（ScienceWorld 累積整合的過度泛化率是孤立任務整合的 5×）</li><li><strong>Overfitting</strong>：輸入分佈過窄，記住表面模式而非底層策略</li></ol></li><li><strong>工程建議</strong>：把 raw episodes 視為 first-class evidence，引入顯式門控（explicit gating），非必要不整合 [P：2605-12978]</li></ul><p><strong>交叉驗證</strong>：ACE [P：2510-04618] 的 brevity bias + context collapse 描述，以及 useful-memories-faulty [P：2605-12978] 的 Misgrouping + Interference，為同一底層問題（LLM-based 整合引入失真）的兩份獨立文獻 [D2]。</p><hr><h3 id="c2-記憶安全與主權" tabindex="-1">C2. 記憶安全與主權 <a class="header-anchor" href="#c2-記憶安全與主權" aria-label="Permalink to &quot;C2. 記憶安全與主權&quot;">​</a></h3><p><strong>Security Survey（Mnemonic Sovereignty）</strong> [P：2604-16548] 識別以下威脅：</p><table tabindex="0"><thead><tr><th>階段</th><th>威脅</th><th>研究密度</th></tr></thead><tbody><tr><td>Write</td><td>注入式投毒（prompt injection into memory）</td><td>高</td></tr><tr><td>Store</td><td>記憶庫竄改</td><td>低</td></tr><tr><td>Retrieve</td><td>對抗性查詢操縱</td><td>高</td></tr><tr><td>Execute</td><td>記憶驅動的惡意行動</td><td>中</td></tr><tr><td>Share</td><td>跨 agent 記憶傳播</td><td>低（研究稀少）</td></tr><tr><td>Forget/Rollback</td><td>拒絕服務（阻止遺忘）</td><td>低</td></tr></tbody></table><ul><li><strong>9 個治理原語</strong> 目前無任何已發表系統完整實作 [P：2604-16548]</li><li><strong>記憶主權（Mnemonic Sovereignty）</strong> 定義為對「寫入內容、讀取者、更新授權、可遺忘狀態」的可驗證、可恢復治理 [P：2604-16548]</li><li>目前安全研究高度集中在 Write/Retrieve 的完整性攻擊，機密性、可用性攻擊「研究稀少」[P：2604-16548]</li></ul><hr><h3 id="c3-三份-survey-框架對齊" tabindex="-1">C3. 三份 Survey 框架對齊 <a class="header-anchor" href="#c3-三份-survey-框架對齊" aria-label="Permalink to &quot;C3. 三份 Survey 框架對齊&quot;">​</a></h3><table tabindex="0"><thead><tr><th>維度</th><th>survey-memory-mechanism [P：2404-13501]</th><th>memory-autonomous-llm-agents-survey [O：2603-07670]</th><th>human-memory-to-ai-memory [O：2504-15965]</th></tr></thead><tbody><tr><td>發表時間</td><td>2024-04</td><td>2026-03</td><td>2025-04</td></tr><tr><td>主要框架</td><td>記憶形式 × 操作 × 應用</td><td>Write-Manage-Read 循環 × 三維分類</td><td>三維八象限（Object × Form × Time）</td></tr><tr><td>記憶形式</td><td>文字、向量、結構化、參數、混合</td><td>向量、圖、語言、代碼</td><td>顯式 vs 隱式（嵌入人類心理學分類）</td></tr><tr><td>操作抽象</td><td>寫入（Always/Selective/Delayed）、讀取、遺忘</td><td>五大機制族群（壓縮/RAG/反思/階層/策略學習）</td><td>感覺→工作→情節→語義→程序</td></tr><tr><td>核心補充</td><td>最完整的早期分類，100+ papers</td><td>最新（2022-2026），強調評估轉向多 session</td><td>生物心理學接地，識別 AI 未覆蓋的維度</td></tr><tr><td><strong>對齊點</strong></td><td>三者均認可 STM/LTM 分層必要性；均指出遺忘策略（Forgetting）研究不足</td><td></td><td></td></tr><tr><td><strong>分歧點</strong></td><td>2404-13501 不含安全維度；2603-07670 補充「學習型遺忘（Learned Forgetting）」作為開放挑戰</td><td></td><td></td></tr></tbody></table><hr><h2 id="d-生產級-memory「控制旋鈕」完整表" tabindex="-1">D. 生產級 Memory「控制旋鈕」完整表 <a class="header-anchor" href="#d-生產級-memory「控制旋鈕」完整表" aria-label="Permalink to &quot;D. 生產級 Memory「控制旋鈕」完整表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>旋鈕</th><th>機制描述</th><th>主要文獻</th><th>失效模式</th><th>緩解策略</th></tr></thead><tbody><tr><td><strong>寫入觸發策略</strong></td><td>Always-write vs Selective-write vs Delayed-write</td><td>2404-13501, 2304-13343 (SCM)</td><td>Always-write 導致記憶膨脹與雜訊；Selective-write 漏記重要事件</td><td>條件式觸發（SCM 的記憶控制器）；重要性評分門檻</td></tr><tr><td><strong>整合頻率（Consolidation Gate）</strong></td><td>控制何時觸發 LLM 重寫記憶</td><td>2605-12978, 2510-04618 (ACE)</td><td>過頻整合觸發 Misgrouping + Interference，utility 退化至 no-memory 以下</td><td><strong>顯式門控</strong>：預設保留 raw episodes，非必要不整合；增量 delta 更新（ACE）而非全文改寫</td></tr><tr><td><strong>遺忘策略</strong></td><td>依時間衰減（遺忘曲線）、熱度分數、LRU 淘汰</td><td>2305-10250 (MemoryBank), 2506-06326 (MemoryOS)</td><td>過激遺忘丟失重要歷史；不遺忘導致無限膨脹與檢索效率下降</td><td>熱度 + 時間的複合評分；LTM vs STM 差異化策略</td></tr><tr><td><strong>分層深度（Tiering Depth）</strong></td><td>STM / MTM / LTM 層數與升格閾值</td><td>2310-08560 (MemGPT), 2506-06326, 2601-01885</td><td>層數太少 → context 溢出；太多 → 升格延遲高，熱資料在冷層</td><td>三層為黃金分割（多篇一致）；熱度感知升格</td></tr><tr><td><strong>檢索策略（Retrieval Strategy）</strong></td><td>Dense（embedding 相似度）/ Sparse（BM25）/ Graph（PPR）/ Temporal（事件日曆）</td><td>2405-14831 (HippoRAG), 2603-16862 (Chronos), 2504-19413 (Mem0)</td><td>Pure dense 失於多跳推理；pure sparse 失於語義泛化；無時序索引失於時間敏感查詢</td><td>混合索引（dense + sparse + graph）；時間感知索引（Chronos SVO calendar）</td></tr><tr><td><strong>記憶形式（Memory Form）</strong></td><td>文字、向量、圖、聯想矩陣、參數</td><td>2505-00675, 2605-12357 (δ-mem), 2405-14831</td><td>純文字缺結構；純向量缺可解釋性；圖構建成本高；參數記憶更新可能干擾原有知識</td><td>混合形式（Mem0 base + graph variant）；依任務選形式</td></tr><tr><td><strong>Context vs Memory 決策點</strong></td><td>短對話保留全上下文；超過約 10 輪或 100K tokens 後改用記憶壓縮</td><td>2603-04814, 2307-03172</td><td>長上下文準確率高但成本隨對話線性增加；記憶壓縮 35:1 但資訊損失顯著</td><td>動態決策：per-session 追蹤 token 用量，crossover 後切換；Lost-in-Middle 的位置偏差意味著結構化檢索仍有價值</td></tr><tr><td><strong>工具記憶（Tool Context）管理</strong></td><td>Autonomous / Workflow / Hybrid 三模式動態工具集增刪</td><td>2507-21428 (MemTool)</td><td>推理模型 Autonomous 模式效率高（90–94%）；中型模型 Autonomous 模式失控（0–60%）</td><td>依模型能力選模式：推理模型用 Autonomous；中型模型用 Hybrid/Workflow</td></tr><tr><td><strong>多代理記憶一致性</strong></td><td>共享 vs 分散記憶架構；快取一致性協議</td><td>2603-10062</td><td>LLM 非確定性推理使傳統快取一致性協議失效；並發寫入導致語義衝突</td><td>樂觀鎖 + 版本戳；語義衝突偵測（研究空白，待解）</td></tr><tr><td><strong>快取層（Prompt Cache）</strong></td><td>System-prompt-only 快取策略</td><td>2601-06007</td><td>動態內容（工具呼叫結果、軌跡）破壞快取前綴 → 快取命中率歸零</td><td>靜態前綴優先（CLAUDE.md 類固定前綴）；動態內容排至尾部</td></tr><tr><td><strong>記憶主權（Mnemonic Sovereignty）</strong></td><td>寫入/讀取/更新/遺忘的治理與存取控制</td><td>2604-16548</td><td>注入式投毒（prompt injection）；跨 agent 未授權傳播；拒絕遺忘攻擊（DoS on Forgetting）</td><td>Write/Retrieve 的完整性驗證；隔離 tenant 記憶；實作 Forget/Rollback 操作（目前 9 個治理原語均未完整實作）</td></tr><tr><td><strong>Episodic 優先原則</strong></td><td>在整合前保留原始 episode 作為 first-class evidence</td><td>2605-12978</td><td>純 episode storage 占用空間大；但 consolidation 引入失真</td><td>ARC-AGI Stream 環境中 Episodic-only ≈ AutoMode（允許自主選擇），均優於 forced-consolidation</td></tr></tbody></table><hr><h2 id="e-關鍵量化數據彙整" tabindex="-1">E. 關鍵量化數據彙整 <a class="header-anchor" href="#e-關鍵量化數據彙整" aria-label="Permalink to &quot;E. 關鍵量化數據彙整&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系統</th><th>Benchmark</th><th>關鍵指標</th><th>來源</th></tr></thead><tbody><tr><td>MemoryOS</td><td>LoCoMo (GPT-4o-mini)</td><td>F1 +49.11%, BLEU-1 +46.18%</td><td>[P：2506-06326]</td></tr><tr><td>Chronos High</td><td>LongMemEvalS (500Q)</td><td><strong>95.60%</strong> 準確率，超次優 7.67%</td><td>[P：2603-16862]</td></tr><tr><td>Hindsight (20B open)</td><td>LongMemEval</td><td><strong>83.6%</strong> vs GPT-4o（超越）</td><td>[P：2512-12818]</td></tr><tr><td>Mem0</td><td>LOCOMO</td><td>+26% vs OpenAI memory；p95 latency -91%</td><td>[P：2504-19413]</td></tr><tr><td>HippoRAG</td><td>Multi-hop QA</td><td>+20% vs RAG，速度 6–13×</td><td>[P：2405-14831]</td></tr><tr><td>δ-mem (8×8 state)</td><td>MemoryAgentBench</td><td>1.31× frozen backbone</td><td>[P：2605-12357]</td></tr><tr><td>RLM (Qwen3-8B)</td><td>Long-context tasks</td><td>中位數 +28%，GPT-5 comparable</td><td>[P：2512-24601]</td></tr><tr><td>ACE</td><td>AppWorld leaderboard</td><td>匹敵 GPT-4.1 top agent（小型開源模型）</td><td>[P：2510-04618]</td></tr><tr><td>Long-context vs Memory</td><td>Multi-task empirical</td><td>Long-context +33.4–35.2 pp，但 10 輪後 Memory 成本有利</td><td>[P：2603-04814]</td></tr><tr><td>Faulty Memory (Consolidation)</td><td>ARC-AGI</td><td>GPT-5.4 失敗率 54%（從成功降至 46%）</td><td>[P：2605-12978]</td></tr></tbody></table><hr><h2 id="覆蓋率表-全-28-篇" tabindex="-1">覆蓋率表（全 28 篇） <a class="header-anchor" href="#覆蓋率表-全-28-篇" aria-label="Permalink to &quot;覆蓋率表（全 28 篇）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>論文識別碼</th><th>本地檔名</th><th>狀態</th><th>引用位置 / 未引用原因</th></tr></thead><tbody><tr><td>1</td><td>2304-13343</td><td>scm-self-controlled-memory</td><td>✅ 已引用</td><td>A1（分層架構）、控制旋鈕表（寫入觸發）</td></tr><tr><td>2</td><td>2305-10250</td><td>memorybank</td><td>✅ 已引用</td><td>A2（遺忘策略）、B1（檢索式）、控制旋鈕表（遺忘策略）</td></tr><tr><td>3</td><td>2310-08560</td><td>memgpt</td><td>✅ 已引用</td><td>A1（OS 類比、分層架構）、控制旋鈕表（分層深度）</td></tr><tr><td>4</td><td>2404-13501</td><td>survey-memory-mechanism-llm-agents</td><td>✅ 已引用</td><td>A1（交叉驗證）、C3（三 survey 對齊）、控制旋鈕表</td></tr><tr><td>5</td><td>2405-14831</td><td>hipporag</td><td>✅ 已引用</td><td>B1（圖檢索）、E（量化）、控制旋鈕表（檢索策略）</td></tr><tr><td>6</td><td>2502-12110</td><td>amem-agentic-memory</td><td>✅ 已引用</td><td>B2（Zettelkasten 自組織）</td></tr><tr><td>7</td><td>2504-07952</td><td>dynamic-cheatsheet-test-time-learning</td><td>✅ 已引用</td><td>B3（Test-time learning）</td></tr><tr><td>8</td><td>2504-15965</td><td>human-memory-to-ai-memory-survey</td><td>✅ 已引用</td><td>C3（三 survey 對齊）、生物心理學框架</td></tr><tr><td>9</td><td>2504-19413</td><td>mem0</td><td>✅ 已引用</td><td>A2（寫入策略）、B1（生產架構）、E（量化）</td></tr><tr><td>10</td><td>2505-00675</td><td>rethinking-memory-llm-agents-operations</td><td>✅ 已引用</td><td>A2（六大操作）、A4（操作抽象）、控制旋鈕表</td></tr><tr><td>11</td><td>2506-06326</td><td>memory-os-ai-agent</td><td>✅ 已引用</td><td>A1（三層架構）、B1（三層檢索）、E（量化）</td></tr><tr><td>12</td><td>2507-21428</td><td>memtool</td><td>✅ 已引用</td><td>B4（工具記憶）、控制旋鈕表（工具記憶）</td></tr><tr><td>13</td><td>2509-25140</td><td>reasoningbank</td><td>✅ 已引用</td><td>B2（推理策略蒸餾）</td></tr><tr><td>14</td><td>2510-04618</td><td>agentic-context-engineering</td><td>✅ 已引用</td><td>B3（ACE playbook）、C1（context collapse）、E（量化）</td></tr><tr><td>15</td><td>2512-12818</td><td>hindsight-agent-memory</td><td>✅ 已引用</td><td>A3（時序控制交叉驗證）、B2（四網絡）、E（量化）</td></tr><tr><td>16</td><td>2512-24601</td><td>recursive-language-models</td><td>✅ 已引用</td><td>B4（RLM 第三條路）、E（量化）</td></tr><tr><td>17</td><td>2601-01885</td><td>agentic-memory-unified-ltm-stm</td><td>✅ 已引用</td><td>A1（AgeMem 統一 LTM+STM）、控制旋鈕表（分層深度）</td></tr><tr><td>18</td><td>2601-06007</td><td>dont-break-cache-prompt-caching</td><td>✅ 已引用</td><td>B5（cache 層）、控制旋鈕表（快取層）</td></tr><tr><td>19</td><td>2603-04814</td><td>beyond-context-window-memory-vs-longcontext</td><td>✅ 已引用</td><td>B4（實証比較）、控制旋鈕表（Context vs Memory）</td></tr><tr><td>20</td><td>2603-07670</td><td>memory-autonomous-llm-agents-survey</td><td>✅ 已引用</td><td>A1（交叉驗證）、C3（三 survey 對齊）</td></tr><tr><td>21</td><td>2603-10062</td><td>multi-agent-memory-computer-architecture</td><td>✅ 已引用</td><td>B6（多代理架構）、控制旋鈕表（多代理一致性）</td></tr><tr><td>22</td><td>2603-16862</td><td>chronos-temporal-aware-conversational-agents</td><td>✅ 已引用</td><td>A3（時序控制）、E（量化）、控制旋鈕表（檢索策略）</td></tr><tr><td>23</td><td>2604-08224</td><td>externalization-llm-agents</td><td>✅ 已引用</td><td>B4（外部化框架）</td></tr><tr><td>24</td><td>2604-16548</td><td>security-long-term-memory-mnemonic-sovereignty</td><td>✅ 已引用</td><td>A4（操作生命週期）、C2（安全威脅）、控制旋鈕表（記憶主權）</td></tr><tr><td>25</td><td>2605-12357</td><td>delta-mem-efficient-online-memory</td><td>✅ 已引用</td><td>A2（線性狀態更新）、E（量化）、控制旋鈕表（記憶形式）</td></tr><tr><td>26</td><td>2307-03172</td><td>lost-in-the-middle</td><td>✅ 已引用</td><td>B4（位置偏差）、控制旋鈕表（Context vs Memory）</td></tr><tr><td>27</td><td>2605-12978</td><td>useful-memories-faulty-llm-continuous-update</td><td>✅ 已引用</td><td>C1（整合退化、三失效機制）、A2（整合風險）、E（量化）</td></tr><tr><td>28</td><td>2307-03172</td><td>lost-in-the-middle（已含於 #26）</td><td>—</td><td>—</td></tr></tbody></table><blockquote><p><strong>覆蓋率：27/27 唯一篇章 = 100%</strong>（去重後 27 篇；#26 與 #28 為同一篇不同登錄）</p></blockquote><hr><h2 id="核心結論-三句" tabindex="-1">核心結論（三句） <a class="header-anchor" href="#核心結論-三句" aria-label="Permalink to &quot;核心結論（三句）&quot;">​</a></h2><ol><li><p><strong>整合是雙刃劍</strong>：記憶整合（Consolidation）是讓記憶「有用」的必要手段，但連續整合本身會以 Misgrouping、Interference、Overfitting 三種機制破壞準確率，在 ARC-AGI 上可讓 GPT-5.4 的成功率從 100% 跌至 46%——生產系統應以 raw episodes 優先、顯式門控整合頻率 [P：2605-12978, 2510-04618]。</p></li><li><p><strong>長上下文非萬靈丹，記憶非廉價替代</strong>：在 10 輪以內長上下文準確率領先 33 個百分點，但超過約 10 輪或 100K tokens 後記憶系統的成本優勢出現；Lost-in-the-Middle 的位置偏差（U 形曲線）則使即使是長上下文方案也需要結構化檢索配合——兩者不是競爭而是互補 [P：2603-04814, 2307-03172]。</p></li><li><p><strong>記憶安全是設計欠債</strong>：現有記憶系統在六階段生命週期中高度集中於 Write/Retrieve 的正確性，但治理（Governance）的 9 個原語目前無任何系統完整實作，跨 agent 記憶傳播、記憶主權、多代理快取一致性均是尚未有工業強度解法的開放問題 [P：2604-16548, 2603-10062]。</p></li></ol>',87)])])}const p=e(n,[["render",a]]);export{c as __pageData,p as default};
